export class GameBoard {
  private cards: Card[];
  private matchedCards: Card[];
  private flippedCards: Card[];
  private moves: number;
  private timer: number;
  private isRunning: boolean;

  constructor() {
    this.cards = [];
    this.matchedCards = [];
    this.flippedCards = [];
    this.moves = 0;
    this.timer = 0;
    this.isRunning = false;
  }

  public initGame(): void {
    this.cards = [];
    this.matchedCards = [];
    this.flippedCards = [];
    this.moves = 0;
    this.timer = 0;
    this.isRunning = true;

    const cardValues = ['A', 'A', 'B', 'B', 'C', 'C', 'D', 'D', 'E', 'E', 'F', 'F'];
    const shuffled = shuffleArray(cardValues);
    for (let i = 0; i < shuffled.length; i++) {
      this.cards.push(new Card(shuffled[i], false));
    }
  }

  public getCards(): Card[] { return this.cards; }
  public getMatchedCards(): Card[] { return this.matchedCards; }
  public getFlippedCards(): Card[] { return this.flippedCards; }
  public getMoves(): number { return this.moves; }
  public getTimer(): number { return this.timer; }
  public getIsRunning(): boolean { return this.isRunning; }

  public flipCard(card: Card): void {
    if (!this.isRunning) return;
    if (this.flippedCards.length >= 2) return;

    this.flippedCards.push(card);
    card.flipped = true;
    this.moves++;
    this.updateTimer();

    if (this.flippedCards.length === 2) {
      const [card1, card2] = this.flippedCards;
      if (card1.value === card2.value) {
        this.matchedCards.push(card1, card2);
        this.flippedCards = [];
        card1.flipped = false;
        card2.flipped = false;
      } else {
        setTimeout(() => {
          card1.flipped = false;
          card2.flipped = false;
          this.flippedCards = [];
        }, 500);
      }
    }
  }

  private updateTimer(): void {
    this.timer = Date.now() / 1000;
  }

  private render(): void {
    const board = document.getElementById('board') as HTMLDivElement;
    board.innerHTML = '';
    for (let i = 0; i < this.cards.length; i++) {
      const card = this.cards[i];
      const cardEl = document.createElement('div');
      cardEl.className = 'card';
      cardEl.dataset.index = i.toString();
      cardEl.innerHTML = `<div class="card-face" style="background-image:url(${card.flipped ? card.image : 'cards/back.png'})">${card.flipped ? card.value : ''}</div>`;
      cardEl.onclick = () => this.flipCard(card);
      board.appendChild(cardEl);
    }
  }

  public startGame(): void {
    this.initGame();
    this.render();
  }

  public resetGame(): void {
    this.isRunning = false;
    this.cards = [];
    this.matchedCards = [];
    this.flippedCards = [];
    this.moves = 0;
    this.timer = 0;
    this.render();
  }

  public isGameOver(): boolean {
    return this.cards.every(card => card.flipped);
  }

  public getScore(): number {
    return this.moves * 10;
  }

  public getProgress(): number {
    const totalVisibleCards = this.cards.filter(card => card.flipped).length;
    return totalVisibleCards / this.cards.length * 100;
  }
}

export class Card {
  constructor(public value: string, public flipped: boolean) {
    this.flipped = flipped;
    this.image = `cards/${value}.png`;
  }

  public flipped: boolean;
  public image: string;
}

function shuffleArray(arr: any[]): any[] {
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [arr[i], arr[j]] = [arr[j], arr[i]];
  }
  return arr;
}

