export class UiScreens {
  private gameBoard: GameBoard;
  private scoreDisplay: HTMLSpanElement;
  private timerDisplay: HTMLSpanElement;
  private movesDisplay: HTMLSpanElement;
  private gameOverPanel: HTMLDivElement;

  constructor() {
    this.gameBoard = new GameBoard();
    this.scoreDisplay = document.createElement('span');
    this.timerDisplay = document.createElement('span');
    this.movesDisplay = document.createElement('span');
    this.gameOverPanel = document.createElement('div');
  }

  public initUI() {
    this.render();
    this.setupEventListeners();
  }

  public render() {
    this.scoreDisplay.textContent = `Score: ${this.gameBoard.getScore()}`;
    this.timerDisplay.textContent = `Time: ${this.gameBoard.getTimer()}`;
    this.movesDisplay.textContent = `Moves: ${this.gameBoard.getMoves()}`;
    this.gameOverPanel.innerHTML = '';
    if (this.gameBoard.isGameOver()) {
      this.gameOverPanel.innerHTML = `
        <h2>🎉 You matched all the cards!</h2>
        <p>Score: ${this.gameBoard.getScore()}</p>
        <button onclick="resetGame()">Play Again</button>
      `;
      this.gameBoard.resetGame();
    } else {
      this.gameBoard.getCards().forEach((card) => {
        const cardEl = document.createElement('div');
        cardEl.className = 'card';
        cardEl.dataset.index = card.index.toString();
        cardEl.innerHTML = `<div class="card-face" style="background-image:url(${card.flipped ? card.image : 'cards/back.png'})">${card.flipped ? card.value : ''}</div>`;
        cardEl.onclick = () => this.flipCard(card);
        this.gameBoard.getCards().push(cardEl);
      });
    }
  }

  public setupEventListeners() {
    this.gameBoard.getCards().forEach((card) => {
      card.addEventListener('click', () => this.flipCard(card));
    });
  }

  public flipCard(card: Card) {
    this.gameBoard.flipCard(card);
    this.render();
  }

  public setupGameOverPanel() {
    this.gameOverPanel.innerHTML = `
      <h2>Game Over</h2>
      <p>Score: ${this.gameBoard.getScore()}</p>
      <p>Time: ${this.gameBoard.getTimer()}</p>
      <p>Moves: ${this.gameBoard.getMoves()}</p>
      <button onclick="resetGame()">Play Again</button>
    `;
    this.gameBoard.getCards().push(this.gameOverPanel);
  }

  public resetGame() {
    this.gameBoard.resetGame();
    this.render();
  }
}

