export class InputHandler {
  private gameBoard: GameBoard;
  private scoreStore: ScoreStore;

  constructor(gameBoard: GameBoard, scoreStore: ScoreStore) {
    this.gameBoard = gameBoard;
    this.scoreStore = scoreStore;
  }

  handleCardFlip(card: Card) {
    this.gameBoard.flipCard(card);
    this.updateScore();
    this.checkForMatch();
  }

  updateScore() {
    const moves = this.gameBoard.getMoves();
    const score = this.scoreStore.getScore();
    this.scoreStore.updateScore(moves, score);
  }

  checkForMatch() {
    const isMatch = this.gameBoard.getMatchedCards().length > 0;
    if (isMatch) {
      this.scoreStore.incrementMatch();
      this.gameBoard.resetFlipped();
    }
  }
}

