export class ScoreStore {
  private storage: Storage;

  constructor() {
    this.storage = new Storage();
  }

  async loadScoreData() {
    const data = await this.storage.get({ key: 'score_data' });
    return data ? JSON.parse(data.value ?? '{}') : {};
  }

  async saveScoreData(scoreData: any) {
    return await this.storage.set({
      key: 'score_data',
      value: JSON.stringify(scoreData, null, 2),
    });
  }
}

